"use client";

import React, { useState, useEffect } from "react";
import { useActionState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ImagePlus, X, Loader2, DollarSign, Gavel, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import { genres, conditions } from "@/lib/mock-data";
import { createVinyl } from "@/lib/actions/vinyls";
import { useRouter } from "next/navigation";
import { useQueryClient } from "@tanstack/react-query";
import { ProtectedAIFeature } from "@/components/protected-ai-feature";
import type { VinylAnalysis } from "@/lib/types";

interface VinylFormProps {
  mode?: "collection" | "listing";
  initialData?: {
    title?: string;
    artist?: string;
    genre?: string;
    year?: number;
    condition?: string;
    sleeveCondition?: string;
    description?: string;
    images?: string; // JSON string
    type?: "new" | "used";
  };
  onSuccess?: () => void;
}

type RecordType = "sealed" | "used" | null;
type PricingType = "fixed" | "auction";

export function VinylForm({ mode = "collection", initialData, onSuccess }: VinylFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();
  const [state, formAction] = useActionState(createVinyl, { error: null });

  // Form state
  const [title, setTitle] = useState(initialData?.title || "");
  const [artist, setArtist] = useState(initialData?.artist || "");
  const [genre, setGenre] = useState(initialData?.genre || "");
  const [year, setYear] = useState(initialData?.year?.toString() || "");
  const [condition, setCondition] = useState(initialData?.condition || "");
  const [sleeveCondition, setSleeveCondition] = useState(initialData?.sleeveCondition || "");
  const [description, setDescription] = useState(initialData?.description || "");
  const [recordType, setRecordType] = useState<RecordType>(
    initialData?.type === "new" ? "sealed" : initialData?.type === "used" ? "used" : null,
  );

  // Image state - for collection: 2-6 images (front/back cover)
  // For listing: 2 if sealed, 4 if used
  const [images, setImages] = useState<Array<{ type: string; url: string }>>(() => {
    if (initialData?.images) {
      try {
        return JSON.parse(initialData.images);
      } catch {
        return [];
      }
    }
    return [];
  });

  // Pricing toggle (only for collection mode)
  const [showPricing, setShowPricing] = useState(false);
  const [pricingType, setPricingType] = useState<PricingType>("fixed");
  const [price, setPrice] = useState("");
  const [startingBid, setStartingBid] = useState("");
  const [reservePrice, setReservePrice] = useState("");
  const [buyItNowPrice, setBuyItNowPrice] = useState("");
  const [auctionDuration, setAuctionDuration] = useState("7");
  const [enableBuyItNow, setEnableBuyItNow] = useState(false);
  const [enableReserve, setEnableReserve] = useState(false);

  // AI analysis state
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<VinylAnalysis | null>(null);

  const handleImageUpload = async (type: string, file: File) => {
    try {
      const formData = new FormData();
      formData.append("file", file);

      const res = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });

      if (!res.ok) throw new Error("Upload failed");

      const { url } = await res.json();

      // For collection: just add to images array (front_cover, back_cover, or additional)
      // For listing: specific types (front_cover, back_cover, vinyl_front, vinyl_back)
      const imageType =
        mode === "collection"
          ? type === "frontCover"
            ? "front_cover"
            : type === "backCover"
              ? "back_cover"
              : `additional_${images.length}`
          : type;

      setImages((prev) => [...prev, { type: imageType, url }]);
    } catch (error) {
      console.error("Image upload error:", error);
      // Error will be shown via state.error if form submission fails
    }
  };

  const removeImage = (index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index));
  };

  const canProceedToAnalysis = () => {
    if (mode === "collection") {
      return images.length >= 2; // Min 2 for collection
    }
    if (recordType === "sealed") {
      return images.some((img) => img.type === "front_cover") && images.some((img) => img.type === "back_cover");
    }
    return (
      images.some((img) => img.type === "front_cover") &&
      images.some((img) => img.type === "back_cover") &&
      images.some((img) => img.type === "vinyl_front") &&
      images.some((img) => img.type === "vinyl_back")
    );
  };

  const handleAnalyzeWithAI = async () => {
    if (!canProceedToAnalysis()) return;

    setIsAnalyzing(true);

    try {
      const imageUrls = images.map((img) => img.url);
      const isSealed = recordType === "sealed" || mode === "collection";

      const response = await fetch("/api/analyze-vinyl", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageUrls,
          isSealed,
        }),
      });

      if (!response.ok) throw new Error("Failed to analyze images");

      const analysis: VinylAnalysis = await response.json();
      setAiAnalysis(analysis);

      // Pre-fill form
      setTitle(analysis.title);
      setArtist(analysis.artist);
      setGenre(analysis.genre);
      setYear(analysis.year);
      setCondition(analysis.condition.overall);
      setSleeveCondition(analysis.condition.sleeveCondition);
      setDescription(analysis.description);
      if (showPricing || mode === "listing") {
        setPrice(analysis.priceEstimate.suggested.toString());
      }
    } catch (error) {
      console.error("Analysis error:", error);
      // Error is logged, user can continue with manual entry
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    if (!title || !artist || !genre || !condition) {
      return;
    }

    if (mode === "collection" && images.length < 2) {
      return;
    }

    if (mode === "listing") {
      if (recordType === "sealed" && images.length < 2) {
        return;
      }
      if (recordType === "used" && images.length < 4) {
        return;
      }
      if (!price && pricingType === "fixed") {
        return;
      }
      if (pricingType === "auction" && !startingBid) {
        return;
      }
    }

    const formData = new FormData();
    formData.set("title", title);
    formData.set("artist", artist);
    formData.set("genre", genre);
    formData.set("year", year || "");
    formData.set("condition", condition);
    formData.set("sleeveCondition", sleeveCondition || condition);
    formData.set("vinylCondition", condition);
    formData.set("type", recordType === "sealed" ? "new" : "used");
    formData.set("description", description || "");
    formData.set("images", JSON.stringify(images));

    const isListed = mode === "listing" || (mode === "collection" && showPricing && price);
    formData.set("isListed", isListed ? "true" : "false");
    formData.set("isInCollection", "true");

    if (isListed) {
      formData.set("price", price || "");
      formData.set("listingType", pricingType);
      if (pricingType === "auction") {
        formData.set("startingBid", startingBid || "");
        formData.set("reservePrice", enableReserve ? reservePrice : "");
        formData.set("buyNowPrice", enableBuyItNow ? buyItNowPrice : "");
        formData.set(
          "auctionEndDate",
          new Date(Date.now() + Number.parseInt(auctionDuration) * 24 * 60 * 60 * 1000).toISOString(),
        );
      }
    }

    const result = await formAction(formData);

    if (!result?.error) {
      // Invalidate queries
      queryClient.invalidateQueries({ queryKey: ["vinyls", "collection"] });
      queryClient.invalidateQueries({ queryKey: ["vinyls", "listings"] });

      if (mode === "listing" || (mode === "collection" && isListed)) {
        router.push("/dashboard/listings");
      } else {
        router.push("/dashboard/collection");
      }

      onSuccess?.();
    }
  };

  const getImageTypeLabel = (index: number) => {
    if (mode === "collection") {
      if (index === 0) return "Front Cover *";
      if (index === 1) return "Back Cover *";
      return `Additional Photo ${index - 1}`;
    }
    // Listing mode
    const types = ["front_cover", "back_cover", "vinyl_front", "vinyl_back"];
    const labels = ["Front Cover *", "Back Cover *", "Vinyl Side A *", "Vinyl Side B *"];
    const type = images[index]?.type;
    const typeIndex = types.indexOf(type || "");
    return typeIndex >= 0 ? labels[typeIndex] : `Image ${index + 1}`;
  };

  const getRequiredImageCount = () => {
    if (mode === "collection") return { min: 2, max: 6 };
    if (recordType === "sealed") return { min: 2, max: 2 };
    return { min: 4, max: 4 };
  };

  const { min: minImages, max: maxImages } = getRequiredImageCount();

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Record Type (only for listing mode) */}
      {mode === "listing" && !recordType && (
        <Card className="border-0 shadow-sm">
          <CardHeader>
            <CardTitle>What are you selling?</CardTitle>
            <CardDescription>This helps us know which images to request</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid sm:grid-cols-2 gap-4">
              <button
                type="button"
                onClick={() => setRecordType("sealed")}
                className={cn(
                  "relative p-6 rounded-xl border-2 text-left transition-all hover:border-primary/50",
                  recordType === "sealed" ? "border-primary bg-primary/5" : "border-border",
                )}
              >
                <Badge variant="secondary" className="text-xs mb-2">2 images required</Badge>
                <h3 className="font-semibold text-lg mb-1">New / Sealed</h3>
                <p className="text-sm text-muted-foreground">Factory sealed or brand new</p>
              </button>
              <button
                type="button"
                onClick={() => setRecordType("used")}
                className={cn(
                  "relative p-6 rounded-xl border-2 text-left transition-all hover:border-primary/50",
                  recordType === "used" ? "border-primary bg-primary/5" : "border-border",
                )}
              >
                <Badge variant="secondary" className="text-xs mb-2">4 images required</Badge>
                <h3 className="font-semibold text-lg mb-1">Used / Opened</h3>
                <p className="text-sm text-muted-foreground">Previously owned</p>
              </button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Images */}
      <Card className="border-0 shadow-sm">
        <CardHeader>
          <CardTitle>Images</CardTitle>
          <CardDescription>
            {mode === "collection"
              ? `Upload ${minImages}-${maxImages} photos (front and back cover required)`
              : recordType === "sealed"
                ? "Upload front and back cover photos"
                : "Upload cover photos and vinyl disc images"}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {/* Existing images */}
            {images.map((img, index) => (
              <div key={index} className="space-y-2">
                <Label className="text-xs text-muted-foreground">{getImageTypeLabel(index)}</Label>
                <div className="relative aspect-square rounded-xl border-2 border-border overflow-hidden bg-muted/30">
                  <img src={img.url} alt={getImageTypeLabel(index)} className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={() => removeImage(index)}
                    className="absolute top-2 right-2 p-1 bg-black/50 rounded-full text-white hover:bg-black/70 transition-colors"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))}

            {/* Upload slots */}
            {images.length < maxImages && (
              <>
                {mode === "collection" ? (
                  // Collection: just front/back or additional
                  images.length < 2 ? (
                    <>
                      {!images.some((img) => img.type === "front_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Front Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("frontCover", file)}
                            label="Front Cover"
                          />
                        </div>
                      )}
                      {!images.some((img) => img.type === "back_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Back Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("backCover", file)}
                            label="Back Cover"
                          />
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="space-y-2">
                      <Label className="text-xs text-muted-foreground">Additional Photo</Label>
                      <ImageUploadSlot
                        onUpload={(file) => handleImageUpload(`additional_${images.length}`, file)}
                        label="Add Photo"
                      />
                    </div>
                  )
                ) : (
                  // Listing: specific types based on record type
                  recordType === "sealed" ? (
                    <>
                      {!images.some((img) => img.type === "front_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Front Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("front_cover", file)}
                            label="Front Cover"
                          />
                        </div>
                      )}
                      {!images.some((img) => img.type === "back_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Back Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("back_cover", file)}
                            label="Back Cover"
                          />
                        </div>
                      )}
                    </>
                  ) : recordType === "used" ? (
                    <>
                      {!images.some((img) => img.type === "front_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Front Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("front_cover", file)}
                            label="Front Cover"
                          />
                        </div>
                      )}
                      {!images.some((img) => img.type === "back_cover") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Back Cover *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("back_cover", file)}
                            label="Back Cover"
                          />
                        </div>
                      )}
                      {!images.some((img) => img.type === "vinyl_front") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Vinyl Side A *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("vinyl_front", file)}
                            label="Vinyl Side A"
                          />
                        </div>
                      )}
                      {!images.some((img) => img.type === "vinyl_back") && (
                        <div className="space-y-2">
                          <Label className="text-xs text-muted-foreground">Vinyl Side B *</Label>
                          <ImageUploadSlot
                            onUpload={(file) => handleImageUpload("vinyl_back", file)}
                            label="Vinyl Side B"
                          />
                        </div>
                      )}
                    </>
                  ) : null
                )}
              </>
            )}
          </div>

          {mode === "listing" && canProceedToAnalysis() && (
            <div className="flex justify-end pt-2">
              <ProtectedAIFeature>
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleAnalyzeWithAI}
                  disabled={isAnalyzing}
                  className="rounded-full"
                >
                  {isAnalyzing ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Analyzing...
                    </>
                  ) : (
                    <>
                      <Sparkles className="h-4 w-4 mr-2" />
                      Analyze with AI
                    </>
                  )}
                </Button>
              </ProtectedAIFeature>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Album Details */}
      <Card className="border-0 shadow-sm">
        <CardHeader>
          <CardTitle>Album Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="title">Title *</Label>
              <Input id="title" value={title} onChange={(e) => setTitle(e.target.value)} required />
            </div>
            <div className="space-y-2">
              <Label htmlFor="artist">Artist *</Label>
              <Input id="artist" value={artist} onChange={(e) => setArtist(e.target.value)} required />
            </div>
            <div className="space-y-2">
              <Label>Genre *</Label>
              <Select value={genre} onValueChange={setGenre}>
                <SelectTrigger>
                  <SelectValue placeholder="Select genre" />
                </SelectTrigger>
                <SelectContent>
                  {genres
                    .filter((g) => g !== "All Genres")
                    .map((g) => (
                      <SelectItem key={g} value={g}>
                        {g}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="year">Year</Label>
              <Input id="year" type="number" value={year} onChange={(e) => setYear(e.target.value)} />
            </div>
            <div className="space-y-2">
              <Label>Condition *</Label>
              <Select value={condition} onValueChange={setCondition}>
                <SelectTrigger>
                  <SelectValue placeholder="Select condition" />
                </SelectTrigger>
                <SelectContent>
                  {conditions.map((c) => (
                    <SelectItem key={c} value={c} className="capitalize">
                      {c.replace("-", " ")}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Sleeve Condition</Label>
              <Select value={sleeveCondition} onValueChange={setSleeveCondition}>
                <SelectTrigger>
                  <SelectValue placeholder="Select condition" />
                </SelectTrigger>
                <SelectContent>
                  {conditions.map((c) => (
                    <SelectItem key={c} value={c} className="capitalize">
                      {c.replace("-", " ")}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={4}
            />
          </div>
        </CardContent>
      </Card>

      {/* Pricing Toggle (only for collection mode) */}
      {mode === "collection" && (
        <Card className="border-0 shadow-sm">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <Label htmlFor="showPricing" className="text-base font-medium">
                  List for Sale
                </Label>
                <p className="text-sm text-muted-foreground">
                  Toggle to add pricing and create a listing instead of just adding to collection
                </p>
              </div>
              <Switch id="showPricing" checked={showPricing} onCheckedChange={setShowPricing} />
            </div>
          </CardContent>
        </Card>
      )}

      {/* Pricing Section */}
      {(mode === "listing" || (mode === "collection" && showPricing)) && (
        <Card className="border-0 shadow-sm">
          <CardHeader>
            <CardTitle>Pricing</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center gap-3">
              <Button
                type="button"
                variant={pricingType === "fixed" ? "default" : "outline"}
                onClick={() => setPricingType("fixed")}
                className="flex-1 rounded-full"
              >
                <DollarSign className="h-4 w-4 mr-2" />
                Fixed Price
              </Button>
              <Button
                type="button"
                variant={pricingType === "auction" ? "default" : "outline"}
                onClick={() => setPricingType("auction")}
                className="flex-1 rounded-full"
              >
                <Gavel className="h-4 w-4 mr-2" />
                Auction
              </Button>
            </div>

            {pricingType === "fixed" ? (
              <div className="space-y-2">
                <Label htmlFor="price">Price *</Label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                  <Input
                    id="price"
                    type="number"
                    step="0.01"
                    min="0"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    className="pl-7"
                    placeholder="0.00"
                    required
                  />
                </div>
                {aiAnalysis && (
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setPrice(aiAnalysis.priceEstimate.suggested.toString())}
                  >
                    <Sparkles className="h-3 w-3 mr-1" />
                    Use AI suggestion: ${aiAnalysis.priceEstimate.suggested}
                  </Button>
                )}
              </div>
            ) : (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="startingBid">Starting Bid *</Label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                    <Input
                      id="startingBid"
                      type="number"
                      step="0.01"
                      min="0"
                      value={startingBid}
                      onChange={(e) => setStartingBid(e.target.value)}
                      className="pl-7"
                      placeholder="0.00"
                      required
                    />
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Switch id="enableReserve" checked={enableReserve} onCheckedChange={setEnableReserve} />
                  <Label htmlFor="enableReserve">Set Reserve Price</Label>
                </div>
                {enableReserve && (
                  <div className="space-y-2">
                    <Label htmlFor="reservePrice">Reserve Price</Label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                      <Input
                        id="reservePrice"
                        type="number"
                        step="0.01"
                        min="0"
                        value={reservePrice}
                        onChange={(e) => setReservePrice(e.target.value)}
                        className="pl-7"
                        placeholder="0.00"
                      />
                    </div>
                  </div>
                )}
                <div className="flex items-center gap-2">
                  <Switch id="enableBuyItNow" checked={enableBuyItNow} onCheckedChange={setEnableBuyItNow} />
                  <Label htmlFor="enableBuyItNow">Enable Buy It Now</Label>
                </div>
                {enableBuyItNow && (
                  <div className="space-y-2">
                    <Label htmlFor="buyItNowPrice">Buy It Now Price</Label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                      <Input
                        id="buyItNowPrice"
                        type="number"
                        step="0.01"
                        min="0"
                        value={buyItNowPrice}
                        onChange={(e) => setBuyItNowPrice(e.target.value)}
                        className="pl-7"
                        placeholder="0.00"
                      />
                    </div>
                  </div>
                )}
                <div className="space-y-2">
                  <Label htmlFor="auctionDuration">Auction Duration (days)</Label>
                  <Select value={auctionDuration} onValueChange={setAuctionDuration}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="3">3 days</SelectItem>
                      <SelectItem value="5">5 days</SelectItem>
                      <SelectItem value="7">7 days</SelectItem>
                      <SelectItem value="10">10 days</SelectItem>
                      <SelectItem value="14">14 days</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {state?.error && (
        <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm">{state.error}</div>
      )}

      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" onClick={() => router.back()} className="rounded-full">
          Cancel
        </Button>
        <Button type="submit" className="rounded-full">
          {mode === "listing" || (mode === "collection" && showPricing) ? (
            "Create Listing"
          ) : (
            "Add to Collection"
          )}
        </Button>
      </div>
    </form>
  );
}

function ImageUploadSlot({ onUpload, label }: { onUpload: (file: File) => void; label: string }) {
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onUpload(file);
    }
  };

  return (
    <div className="relative aspect-square rounded-xl border-2 border-dashed border-border overflow-hidden group cursor-pointer hover:border-primary transition-colors bg-muted/30">
      <div className="absolute inset-0 flex flex-col items-center justify-center text-muted-foreground">
        <ImagePlus className="h-8 w-8 mb-2" />
        <span className="text-xs">{label}</span>
      </div>
      <input
        type="file"
        accept="image/*"
        onChange={handleFileChange}
        className="absolute inset-0 opacity-0 cursor-pointer"
      />
    </div>
  );
}
